import{z as B,x as A,o as r,c as d,q as l,j as n,D as E,d as o,s as i,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"底层设计与二次电子","description":"","frontmatter":{"title":"底层设计与二次电子","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/underlayer-secondary-electron.md","filePath":"litho/underlayer-secondary-electron.md","lastUpdated":1791413859000}'),p={name:"litho/underlayer-secondary-electron.md"};function h(u,a,m,c,f,D){const t=A("Mermaid");return r(),d("div",null,[a[2]||(a[2]=l('<h1 id="底层设计与二次电子" tabindex="-1">底层设计与二次电子 <a class="header-anchor" href="#底层设计与二次电子" aria-label="Permalink to &quot;底层设计与二次电子&quot;">​</a></h1><div class="epigraph"><p>薄胶的界面是电子的出入口。底层可以提高二次电子产额来补灵敏度，也会把底部模糊和 footing 写成侧壁。</p><footer>—— 据 Naulleau 二次电子模糊；Kozawa 电离产酸；Levinson 底层功能</footer></div><p><a href="/litho/euv-resist-absorption">上一课</a>把膜厚和吸收系数锁在一起。缺口是膜下面那一层：事件不仅生于胶内吸收，也生于底层射上来的二次电子。<a href="/litho/euv-underlayer">EUV 底层</a> 已列功能栈；<a href="/litho/euv-secondary-electron">二次电子产额</a> 已给产额语言。本课把两者收成设计旋钮。高 NA 下这张薄栈如何转印，留给<a href="/litho/high-na-pattern-transfer">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>吸收课假设光子在胶内变成事件。胶只有十几纳米时，界面占比巨大：底层高 Z 或高密度会抬二次电子产额，等效增加底部剂量，灵敏度「免费」上升；同时底部模糊核加厚，清底与 footing 和光学离焦同貌。设计缺口是：用底层补 \\(\\bar N\\) 时，能补多少、侧壁还能不能立。不是再列黏附、平面化、硬掩模清单。</p><p><span class="marginnote">给个能量直觉：一个 EUV 光子约 92 eV，是 193 nm DUV 光子（约 6.4 eV）的十几倍。能量富余意味着一个光子能撞出一整串二次电子——所以底层的元素选择对灵敏度影响巨大，这是 DUV 时代没有的旋钮。</span></p><p>CAR 对底层酸碱敏感，衬底淬灭出 footing；金属氧化物对界面黏附和显影钻蚀敏感。二次电子是第三条、EUV 特有的耦合。</p><p><span class="marginnote">底层不是光学透明垫片。换 underlayer 等于换胶模型的界面源项，OPC 要紧凑模型重校准。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实验：同一胶只换底层，看 \\(E_0\\)、侧壁、LER 高频和孔缺失。产额升而剖面倒锥，说明底部事件过密。产额低而膜又薄，随机先爆——应加 \\(\\alpha\\) 或 \\(D\\)，而不是只怪 SMO。栈：黏附层、电子调节层、硬掩模可以是一层或两层，电子调节与硬掩模的元素选择往往冲突（高 Z 利电子、未必利蚀刻）。</p><p><span class="marginnote">常见误区：以为灵敏度提升白拿。底层灌电子确实让同一剂量更容易成像，但底部事件变密会把模糊和 footing 写进侧壁——灵敏度和分辨率在这张账上是耦合的，不能只挑好的那头。</span></p><p>与吸收：胶内 \\(\\alpha t\\) 与界面产额是两源。模型要能分开，否则加剂量和换底层在仿真里不可区分。</p><h3 id="电子调节与硬掩模常常打架" tabindex="-1">电子调节与硬掩模常常打架 <a class="header-anchor" href="#电子调节与硬掩模常常打架" aria-label="Permalink to &quot;电子调节与硬掩模常常打架&quot;">​</a></h3><p>高 Z 底层利二次电子和灵敏度，干法选择比和金属沾污未必合格。含硅硬掩模利转印，电子产额可能不够。两层栈把功能拆开：薄电子层贴胶、厚硬掩模在下。涂布混合、烘烤互扩散会把两层重新搅在一起，窗口实验必须声明栈，不能只报「一种底层」。</p>',14)),(r(),n(s,null,{default:E(()=>[i(t,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20PH%5B%22%E8%83%B6%E5%86%85%E5%90%B8%E6%94%B6%22%5D%20--%3E%20EV%5B%22%E5%8C%96%E5%AD%A6%E4%BA%8B%E4%BB%B6%22%5D%0A%20%20UL%5B%22%E5%BA%95%E5%B1%82%E4%BA%8C%E6%AC%A1%E7%94%B5%E5%AD%90%22%5D%20--%3E%20EV%0A%20%20EV%20--%3E%20SENS%5B%22%E7%81%B5%E6%95%8F%E5%BA%A6%22%5D%0A%20%20UL%20--%3E%20BLUR%5B%22%E5%BA%95%E9%83%A8%E6%A8%A1%E7%B3%8A%20%2F%20footing%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[o("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"92 eV 光子在底层电离，电子级联，射程纳米量级，一部分越过界面进入胶。Naulleau 的模糊核、Kozawa 的电离产酸，在界面处变成轴向不对称：底部事件密度高于按胶内 Beer 定律的外推。热化距离随材料变，本课不编射程表，只要求资格认证声明底层。氢和真空污染课的出气，底层也是源之一，设计还要低放气。",-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"「二次电子」就是被 EUV 光子打出的第一代电子再去撞别的原子、撞出来的下一级电子——像台球开球后的连续碰撞。级联几代后能量降到几电子伏，飞不了几纳米，所以它的危害与贡献都锁在界面附近。")],-1)),(r(),n(s,null,{default:E(()=>[i(t,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E5%85%89%E5%88%BB%E8%83%B6%22%5D%20--%3E%20E%5B%22%E8%96%84%E7%94%B5%E5%AD%90%E8%B0%83%E8%8A%82%E5%B1%82%22%5D%0A%20%20E%20--%3E%20HM%5B%22%E5%8E%9A%E7%A1%AC%E6%8E%A9%E6%A8%A1%E5%B1%82%22%5D%0A%20%20E%20--%3E%20Y%5B%22%E6%8A%AC%E4%BA%8C%E6%AC%A1%E7%94%B5%E5%AD%90%E4%BA%A7%E9%A2%9D%EF%BC%8C%E8%A1%A5%E7%81%B5%E6%95%8F%E5%BA%A6%22%5D%0A%20%20HM%20--%3E%20S%5B%22%E6%89%9B%E5%B9%B2%E6%B3%95%E8%9A%80%E5%88%BB%EF%BC%8C%E8%BD%AC%E5%8D%B0%E5%9B%BE%E5%BD%A2%22%5D%0A%20%20E%20-.%20%22%E7%83%98%E7%83%A4%E4%BA%92%E6%89%A9%E6%95%A3%22%20.-%3E%20MIX%5B%22%E4%B8%A4%E5%B1%82%E6%90%85%E6%B7%B7%22%5D%0A%20%20MIX%20--%3E%20BOTH%5B%22%E7%94%B5%E5%AD%90%E4%B8%8E%E8%9A%80%E5%88%BB%E5%8A%9F%E8%83%BD%E5%90%8C%E6%97%B6%E5%8A%A3%E5%8C%96%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<p><span class="marginnote">「更敏的底层」可能是电子灌入，也可能是界面不淬灭酸。要用剖面和随机曲线拆，不能只看 Esize。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写干法如何把 15 nm 浮雕传到硬掩模，下一课才写高 NA 薄胶转印。不重写 BARC 驻波——EUV 驻波不是第一理由。界面电子是轴向不对称模糊，不能用对称高斯酸核代替。出处：Naulleau；Kozawa；Levinson；底层与产额课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>底层二次电子是薄胶灵敏度的设计旋钮，也是底部模糊源。</li><li>与胶内吸收分源建模；换底层要重校准 OPC。</li><li>下一课：这张薄潜像怎样变成可蚀刻的硬掩模图形。</li><li>出处：Naulleau、Kozawa、Levinson。</li></ul>',5))])}const V=B(p,[["render",h]]);export{C as __pageData,V as default};
